Hi All,

I'm expecting the terraform config to appear in the json output. I need the instance type and potentially also the ami, but I'm not seeing it. Thanks!


### Terraform Version

4e14ab755758c312c8b4664722c0ac4aefcbb005

### Terraform Configuration Files
```hcl
resource "aws_instance" "basic" {
  ami = "ami-0a16c82eb0cc3aad8"
  instance_type = "t2.micro"
  key_name = "aws-test-west"
}

provider "aws" {
    region = "us-west-1"
}
```

### Actual Output
```json
{
  "format_version": "0.1",
  "planned_values": {
    "root_module": {
      "resources": [
        {
          "address": "aws_instance.basic",
          "mode": "managed",
          "type": "aws_instance",
          "name": "basic",
          "provider_name": "aws",
          "schema_version": 1
        }
      ]
    }
  },
  "resource_changes": [
    {
      "address": "aws_instance.basic",
      "mode": "managed",
      "type": "aws_instance",
      "name": "basic",
      "deposed": true,
      "change": {
        "actions": [
          "Create"
        ],
        "before": null
      }
    }
  ],
  "configuration": {
    "provider_config": {
      "aws": {
        "name": "aws",
        "expressions": {
          "region": {
            "constant_value": "us-west-1"
          }
        }
      }
    },
    "root_module": {
      "resources": [
        {
          "address": "aws_instance.basic",
          "mode": "managed",
          "type": "aws_instance",
          "name": "basic",
          "provider_config_key": "provider.aws",
          "schema_version": 0,
          "count_expression": {},
          "for_each_expression": {}
        }
      ]
    }
  }
}
```

### Steps to Reproduce
1. terraform init
2. terraform plan -out terraform.tfplan
3. terraform show -json terraform.tfplan
